function hammingWeight(n: number): number {
  let count = 0;

  // Каждая итерация «гасит» одну единицу, поэтому
  // цикл выполнится ровно столько раз, сколько единиц в n
  while (n !== 0) {
    // n - 1 превращает младшую единицу в 0, а нули правее неё — в единицы.
    // n & (n - 1) поэтому сбрасывает ровно младшую единицу:
    // 1011 & 1010 = 1010, 1010 & 1001 = 1000, 1000 & 0111 = 0000
    n &= n - 1;
    count++;
  }

  return count;
}

// Время: O(k), k — число единичных битов (не больше 32)
// Память: O(1)
